# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HRİSTİYANLIĞIN DOĞUŞU VE HZ. İSA TASAVVURU KARŞILAŞTIRMASI</text>\n  <rect x="20" y="48" width="320" height="172" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">HRİSTİYAN GELENEĞİNE GÖRE</text>\n  <rect x="34" y="84" width="292" height="122" rx="6" fill="#ffffff" stroke="#60a5fa" stroke-width="1"/>\n  <text x="180" y="105" text-anchor="middle" font-size="10" fill="#334155">• Mesih (Hristos): Beklenen ilahi kurtarıcıdır.</text>\n  <text x="180" y="125" text-anchor="middle" font-size="10" fill="#334155">• Teslisin ikinci unsuru (\'Tanrı\'nın Oğlu\') sayılır.</text>\n  <text x="180" y="145" text-anchor="middle" font-size="10" fill="#334155">• Asli günahın kefareti için çarmıhta ölmüştür.</text>\n  <text x="180" y="165" text-anchor="middle" font-size="10" fill="#334155">• Üç gün sonra dirilip göğe yükselmiştir.</text>\n  <text x="180" y="188" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">• On iki yardımcısına \'Havari\' adı verilir.</text>\n  <rect x="360" y="48" width="320" height="172" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">İSLAM İNANCINA GÖRE (Kur\'an-ı Kerim)</text>\n  <rect x="374" y="84" width="292" height="122" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1"/>\n  <text x="520" y="105" text-anchor="middle" font-size="10" fill="#334155">• Hz. Meryem\'den babasız doğan mucize peygamberdir.</text>\n  <text x="520" y="125" text-anchor="middle" font-size="10" fill="#334155">• İlah veya Allah\'ın oğlu değil; kulu ve resulüdür.</text>\n  <text x="520" y="145" text-anchor="middle" font-size="10" fill="#334155">• Ulü\'l-azm peygamberlerden biridir, İncil verilmiştir.</text>\n  <text x="520" y="165" text-anchor="middle" font-size="10" fill="#334155">• Çarmıha gerilmemiş ve öldürülmemiştir (Nisâ, 157).</text>\n  <text x="520" y="188" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">• Yüce Allah onu kendi katına yükseltmiştir.</text>\n</svg>', '<svg viewBox="0 0 700 235" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="235" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HRİSTİYANLIĞIN TARİHSEL DÖNÜM NOKTALARI VE KONSİLLER</text>\n  <rect x="18" y="46" width="155" height="168" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="95" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">1. TARSUSLU PAVLUS</text>\n  <text x="95" y="92" text-anchor="middle" font-size="9.5" fill="#334155">• Yahudi şeriatını (sünnet,</text>\n  <text x="95" y="108" text-anchor="middle" font-size="9.5" fill="#334155">koşer, Sebt) kaldırdı.</text>\n  <text x="95" y="128" text-anchor="middle" font-size="9.5" fill="#334155">• Asli günah ve kefaret</text>\n  <text x="95" y="144" text-anchor="middle" font-size="9.5" fill="#334155">doktrinini kurdu.</text>\n  <text x="95" y="164" text-anchor="middle" font-size="9.5" fill="#334155">• Roma dünyasına yaydı.</text>\n  <rect x="187" y="46" width="155" height="168" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="264" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">2. MİLANO (313)</text>\n  <text x="264" y="92" text-anchor="middle" font-size="9.5" fill="#334155">• İmparator I. Konstantin</text>\n  <text x="264" y="108" text-anchor="middle" font-size="9.5" fill="#334155">tarafından ilan edildi.</text>\n  <text x="264" y="128" text-anchor="middle" font-size="9.5" fill="#334155">• Roma baskısı sona erdi,</text>\n  <text x="264" y="144" text-anchor="middle" font-size="9.5" fill="#334155">din serbest bırakıldı.</text>\n  <text x="264" y="164" text-anchor="middle" font-size="9.5" fill="#334155">• 380\'de resmî din oldu.</text>\n  <rect x="356" y="46" width="155" height="168" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="433" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">3. İZNİK KONSİLİ (325)</text>\n  <text x="433" y="92" text-anchor="middle" font-size="9.5" fill="#334155">• Arius\'un tevhidci görüşü</text>\n  <text x="433" y="108" text-anchor="middle" font-size="9.5" fill="#334155">reddedilip aforoz edildi.</text>\n  <text x="433" y="128" text-anchor="middle" font-size="9.5" fill="#334155">• İsa\'nın Baba ile aynı</text>\n  <text x="433" y="144" text-anchor="middle" font-size="9.5" fill="#334155">özden olduğu kabul edildi.</text>\n  <text x="433" y="164" text-anchor="middle" font-size="9.5" fill="#334155">• 4 İncil kanonik sayıldı.</text>\n  <rect x="525" y="46" width="157" height="168" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="603" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">4. İSTANBUL (381)</text>\n  <text x="603" y="92" text-anchor="middle" font-size="9.5" fill="#334155">• Kutsal Ruh\'un tanrılığı</text>\n  <text x="603" y="108" text-anchor="middle" font-size="9.5" fill="#334155">resmen kabul edildi.</text>\n  <text x="603" y="128" text-anchor="middle" font-size="9.5" fill="#334155">• Teslis (Baba - Oğul -</text>\n  <text x="603" y="144" text-anchor="middle" font-size="9.5" fill="#334155">Kutsal Ruh) tamamlandı.</text>\n  <text x="603" y="164" text-anchor="middle" font-size="9.5" fill="#334155">• İznik-İstanbul Amentüsü</text>\n</svg>', '<svg viewBox="0 0 700 235" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="235" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HRİSTİYAN KUTSAL METİN KÜLLİYATI: KİTÂB-I MUKADDES</text>\n  <rect x="20" y="45" width="215" height="170" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. ESKİ AHİT (Ahd-i Atîk)</text>\n  <rect x="32" y="80" width="191" height="122" rx="6" fill="#ffffff" stroke="#fbbf24" stroke-width="1"/>\n  <text x="127" y="100" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Yahudi Tanah Külliyatı (39 Bölüm)</text>\n  <text x="127" y="122" text-anchor="middle" font-size="10" fill="#334155">• Tora (Tevrat): 5 Bölüm</text>\n  <text x="127" y="142" text-anchor="middle" font-size="10" fill="#334155">• Neviim (Peygamberler)</text>\n  <text x="127" y="162" text-anchor="middle" font-size="10" fill="#334155">• Ketuvim (Yazılar / Mezmurlar)</text>\n  <text x="127" y="186" text-anchor="middle" font-size="9.5" fill="#64748b">Hz. İsa öncesi peygamberler tarihi</text>\n  <rect x="255" y="45" width="425" height="170" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="467" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. YENİ AHİT (Ahd-i Cedîd — Toplam 27 Bölüm)</text>\n  <rect x="268" y="80" width="194" height="122" rx="6" fill="#ffffff" stroke="#60a5fa" stroke-width="1"/>\n  <text x="365" y="100" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">A) Dört Kanonik İncil</text>\n  <text x="365" y="120" text-anchor="middle" font-size="9.5" fill="#166534">• Matta, Markos, Luka (Sinoptikler)</text>\n  <text x="365" y="138" text-anchor="middle" font-size="9.5" fill="#334155">• Yuhanna (Teolojik/Logos İncili)</text>\n  <text x="365" y="162" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">B) Elçilerin İşleri (1 Bölüm)</text>\n  <text x="365" y="180" text-anchor="middle" font-size="9.5" fill="#334155">• Havarilerin tebliğ faaliyetleri</text>\n  <rect x="474" y="80" width="194" height="122" rx="6" fill="#ffffff" stroke="#60a5fa" stroke-width="1"/>\n  <text x="571" y="100" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">C) Mektuplar (21 Bölüm)</text>\n  <text x="571" y="120" text-anchor="middle" font-size="9.5" fill="#334155">• Pavlus\'un Mektupları (13/14 adet)</text>\n  <text x="571" y="138" text-anchor="middle" font-size="9.5" fill="#334155">• Katolik (Genel) Mektuplar (7 adet)</text>\n  <text x="571" y="162" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">D) Vahiy / Apokalips (1 Bölüm)</text>\n  <text x="571" y="180" text-anchor="middle" font-size="9.5" fill="#334155">• Yuhanna\'ya atfedilen kıyamet metni</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
